import {useMemo} from 'react'

import styles from './CopilotAppLauncher.module.css'

export interface WordRevealSegment {
  text: string
  className?: string
}

interface WordRevealProps {
  children: WordRevealSegment[]
  baseDelay?: number
  wordDelay?: number
}

/**
 * Reveals text word-by-word with staggered fade-in animations.
 * Supports mixed styling (bold/muted) across segments.
 * Respects `prefers-reduced-motion` via CSS.
 */
export function WordReveal({children, baseDelay = 0, wordDelay = 60}: WordRevealProps) {
  const words = useMemo(() => {
    const result: Array<{
      word: string
      className?: string
      index: number
      wordKey: string
    }> = []
    let globalIndex = 0
    let charOffset = 0
    for (const segment of children) {
      const segmentWords = segment.text.split(/(\s+)/)
      for (const word of segmentWords) {
        if (word.length === 0) continue
        result.push({
          word,
          className: segment.className,
          index: globalIndex,
          wordKey: `${charOffset}-${word.slice(0, 8)}`,
        })
        charOffset += word.length
        if (word.trim().length > 0) {
          globalIndex++
        }
      }
    }
    return result
  }, [children])

  return (
    <>
      {words.map(entry => {
        const isWhitespace = entry.word.trim().length === 0
        if (isWhitespace) {
          return (
            <span key={entry.wordKey} className={entry.className}>
              {entry.word}
            </span>
          )
        }
        const delay = baseDelay + entry.index * wordDelay
        return (
          <span
            key={entry.wordKey}
            className={`${styles.WordRevealWord} ${styles.WordRevealAnimate} ${entry.className ?? ''}`}
            style={{animationDelay: `${delay}ms`}}
          >
            {entry.word}
          </span>
        )
      })}
    </>
  )
}
