import {getOS, OS, type NavigatorUserAgent, type OS as OperatingSystem} from '@github-ui/get-os'
import {useEffect, useMemo, useState, useSyncExternalStore} from 'react'

export type DownloadArch = 'arm' | 'x86'
export type DownloadPlatform = typeof OS.macOS | typeof OS.Windows | typeof OS.Linux
type ResolvableDownloadPlatform = DownloadPlatform | typeof OS.Unknown

export interface DownloadItem {
  platform: DownloadPlatform
  arch?: DownloadArch
  label: string
  href: string
}

export const DOWNLOAD_ITEMS: readonly [DownloadItem, ...DownloadItem[]] = [
  {
    platform: OS.macOS,
    arch: 'arm',
    label: 'Download for macOS (Silicon)',
    href: 'https://gh.io/copilot-app-mac',
  },
  {
    platform: OS.macOS,
    arch: 'x86',
    label: 'Download for macOS (Intel)',
    href: 'https://gh.io/copilot-app-mac-intel',
  },
  {
    platform: OS.Windows,
    arch: 'arm',
    label: 'Download for Windows (ARM)',
    href: 'https://gh.io/copilot-app-win-arm',
  },
  {
    platform: OS.Windows,
    // UA-CH reports `architecture: "x86"` for x86-family CPUs; bitness is a separate hint.
    arch: 'x86',
    label: 'Download for Windows (x64)',
    href: 'https://gh.io/copilot-app-win64',
  },
  {
    platform: OS.Linux,
    label: 'Download for Linux',
    href: 'https://gh.io/copilot-app-linux',
  },
]

const DEFAULT_DOWNLOAD_ITEM = DOWNLOAD_ITEMS[0]
const DEFAULT_ARCH_BY_PLATFORM: Partial<Record<DownloadPlatform, DownloadArch>> = {
  [OS.macOS]: 'arm',
  [OS.Windows]: 'x86',
}

function isDownloadPlatform(os: OperatingSystem): os is DownloadPlatform {
  return os === OS.macOS || os === OS.Windows || os === OS.Linux
}

function getBrowserDownloadPlatform() {
  const {os} = getOS()
  return isDownloadPlatform(os) ? os : OS.Unknown
}

function getServerDownloadPlatform() {
  return OS.Unknown
}

function subscribeToDownloadPlatform() {
  return () => {}
}

function useDownloadPlatform() {
  return useSyncExternalStore(subscribeToDownloadPlatform, getBrowserDownloadPlatform, getServerDownloadPlatform)
}

export function resolveDownloadItem(platform: ResolvableDownloadPlatform, arch?: DownloadArch) {
  const platformItems = DOWNLOAD_ITEMS.filter(item => item.platform === platform)
  const fallbackItem = platformItems[0]
  if (!fallbackItem) return DEFAULT_DOWNLOAD_ITEM

  if (arch) {
    const archMatch = platformItems.find(item => item.arch === arch)
    if (archMatch) return archMatch
  }

  const preferredArch = isDownloadPlatform(platform) ? DEFAULT_ARCH_BY_PLATFORM[platform] : undefined
  if (preferredArch) {
    const preferredMatch = platformItems.find(item => item.arch === preferredArch)
    if (preferredMatch) return preferredMatch
  }

  return fallbackItem
}

export function useResolvedDownloadItem() {
  const platform = useDownloadPlatform()
  const [resolvedArch, setResolvedArch] = useState<DownloadArch | undefined>(undefined)

  useEffect(() => {
    if (typeof window === 'undefined') return

    const uaData = (window.navigator as Navigator & NavigatorUserAgent).userAgentData
    const getHighEntropyValues = uaData?.getHighEntropyValues?.bind(uaData)
    if (!getHighEntropyValues) return

    let cancelled = false

    const detectArch = async () => {
      try {
        const values = await getHighEntropyValues(['architecture'])
        if (cancelled) return

        const arch = values.architecture === 'arm' || values.architecture === 'x86' ? values.architecture : undefined
        setResolvedArch(arch)
      } catch {
        // Architecture detection is best-effort; keep the OS-level download.
      }
    }

    void detectArch()

    return () => {
      cancelled = true
    }
  }, [])

  return useMemo(() => resolveDownloadItem(platform, resolvedArch), [platform, resolvedArch])
}
